-- Seed: the product pictures found for each model (web images, licence NOT verified, shown with attribution, switchable off with FEATURE_FLAGS.web_images).
-- They are data, not code: without these rows the app shows only the drawn laptop and no "Show photo" button.
-- Only rows for variants that exist in this database are inserted; running it twice changes nothing.
insert into laptop_image (variant_id, url, page_url, site, description, position, licence_status)
select v.variant_id, v.url, v.page_url, v.site, v.description, v.position, 'unverified_web'
from (values
  ('FKL-01', 'https://rukminim2.flixcart.com/image/480/480/xif0q/computer/k/k/r/fa706ihrb-hx041w-gaming-laptop-asus-original-imah3my8kb6tsnky.jpeg?q=80', null, 'rukminim2.flixcart.com', 'The ASUS TUF Gaming A17 laptop is showcased in a sleek advertisement, featuring its graphite black design, 90Whr battery, and Ryzen 5 hexa-core AMD R5-4600H processor, with the tagline "STUN with STYLE" prominently displayed.', 0),
