  ('FKL-02', 'https://rukminim2.flixcart.com/image/480/640/kwdv3bk0/computer/9/p/h/15-ec2145ax-gaming-laptop-hp-original-imag92vpygkagh5g.jpeg?q=80', null, 'rukminim2.flixcart.com', 'The advertisement showcases a sleek black HP Pavilion laptop with a hexa-core AMD Ryzen 5 5600H processor, featuring a vibrant screen displaying a video game and emphasizing its powerful audio experience with dual speakers and a special BO audio technology.', 1),
